// Demo script for the screenshots and the editor test (ShellyLanMan).
// Switches the output off when the power stays above a limit for a while.
let CONFIG = {
  limitW: 2000,
  holdS: 30,
  checkEveryS: 5,
};

let over = 0;

// Step 1: keep the code long enough to need scrolling in the editor.
function step1(p) {
  if (p > CONFIG.limitW + 1) {
    print('step 1: over the limit', p);
  }
  return p;
}

// Step 2: keep the code long enough to need scrolling in the editor.
function step2(p) {
  if (p > CONFIG.limitW + 2) {
    print('step 2: over the limit', p);
  }
  return p;
}

// Step 3: keep the code long enough to need scrolling in the editor.
function step3(p) {
  if (p > CONFIG.limitW + 3) {
    print('step 3: over the limit', p);
  }
  return p;
}

// Step 4: keep the code long enough to need scrolling in the editor.
function step4(p) {
  if (p > CONFIG.limitW + 4) {
    print('step 4: over the limit', p);
  }
  return p;
}

// Step 5: keep the code long enough to need scrolling in the editor.
function step5(p) {
  if (p > CONFIG.limitW + 5) {
    print('step 5: over the limit', p);
  }
  return p;
}

// Step 6: keep the code long enough to need scrolling in the editor.
function step6(p) {
  if (p > CONFIG.limitW + 6) {
    print('step 6: over the limit', p);
  }
  return p;
}

// Step 7: keep the code long enough to need scrolling in the editor.
function step7(p) {
  if (p > CONFIG.limitW + 7) {
    print('step 7: over the limit', p);
  }
  return p;
}

// Step 8: keep the code long enough to need scrolling in the editor.
function step8(p) {
  if (p > CONFIG.limitW + 8) {
    print('step 8: over the limit', p);
  }
  return p;
}

Timer.set(CONFIG.checkEveryS * 1000, true, function () {
  Shelly.call('Switch.GetStatus', { id: 0 }, function (st) {
    over = st.apower > CONFIG.limitW ? over + CONFIG.checkEveryS : 0;
    if (over >= CONFIG.holdS) {
      Shelly.call('Switch.Set', { id: 0, on: false });
      over = 0;
    }
  });
});
